const q = (id, themeId, critical, prompt, choices, correctIndex, rationale, source) => {
  // Les bonnes réponses sont réparties dans les quatre positions pour éviter
  // qu’une habitude de clic ne remplace la connaissance métier.
  const offset = Number(id.slice(2)) % choices.length
  const rotatedChoices = choices.slice(offset).concat(choices.slice(0, offset))
  const rotatedCorrectIndex = (correctIndex - offset + choices.length) % choices.length
  return { id, themeId, status: 'published', critical, prompt, choices: rotatedChoices, correctIndex: rotatedCorrectIndex, rationale, source }
}

